  1→import {
  2→  concurrentSeries,
  3→  parseRows,
  4→  type ConcurrencyPoint,
  5→  type Row,
  6→  type RunEvent,
  7→} from "./timeline";
  8→
  9→type Json = Record<string, unknown>;
 10→
 11→interface Snapshot {
 12→  run_id: string;
 13→  status: string;
 14→  n: number;
 15→  steps: Array<{
 16→    id: string;
 17→    state: string;
 18→    attempts: number;
 19→    next_attempt_at: number | null;
 20→  }>;
 21→  final_text: string | null;
 22→  last_seq: number;
 23→}
 24→
 25→interface RunRecord {
 26→  run_id: string;
 27→  n: number;
 28→  status: string;
 29→  duration_ms: number | null;
 30→}
 31→
 32→const TOOLS = ["search", "summarize", "generate_image"] as const;
 33→const FINISHED = new Set(["SUCCEEDED", "FAILED", "PARTIAL", "CANCELLED"]);
 34→
 35→const byId = <T extends HTMLElement>(id: string): T => {
 36→  const node = document.getElementById(id);
 37→  if (!node) {
 38→    throw new Error(`missing element: ${id}`);
 39→  }
 40→  return node as T;
 41→};
 42→
 43→const ui = {
 44→  plan: byId<HTMLTextAreaElement>("plan-input"),
 45→  loadExample: byId<HTMLButtonElement>("load-example"),
 46→  concurrency: byId<HTMLInputElement>("concurrency"),
 47→  run: byId<HTMLButtonElement>("run-button"),
 48→  cancel: byId<HTMLButtonElement>("cancel-button"),
 49→  errors: byId<HTMLPreElement>("errors"),
 50→  status: byId<HTMLDivElement>("status"),
 51→  final: byId<HTMLDivElement>("final-text"),
 52→  chart: byId<HTMLDivElement>("concurrency-chart"),
 53→  timeline: byId<HTMLDivElement>("timeline"),
 54→  eventTable: byId<HTMLTableSectionElement>("event-table"),
 55→  history: byId<HTMLTableSectionElement>("run-history"),
 56→};
 57→
 58→let runId: string | null = null;
 59→let events: RunEvent[] = [];
 60→let lastSeq = 0;
 61→let currentN = 2;
 62→let source: EventSource | null = null;
 63→const runs: RunRecord[] = [];
 64→
 65→async function fetchJson<T>(url: string, init?: RequestInit): Promise<{ status: number; body: T }> {
 66→  const response = await fetch(url, init);
 67→  const text = await response.text();
 68→  let body = {} as T;
 69→  if (text) {
 70→    try {
 71→      body = JSON.parse(text) as T;
 72→    } catch {
 73→      body = {} as T;
 74→    }
 75→  }
 76→  return { status: response.status, body };
 77→}
 78→
 79→function showErrors(status: number, payload: unknown): void {
 80→  const data = (payload ?? {}) as Json;
 81→  const items: Json[] = [];
 82→  if (Array.isArray(data.errors)) {
 83→    items.push(...(data.errors as Json[]));
 84→  }
 85→  if (items.length === 0 && Array.isArray(data.detail)) {
 86→    items.push(...(data.detail as Json[]));
 87→  }
 88→  const lines = items.map((item) => {
 89→    const code = String(item.error ?? item.type ?? item.msg ?? "invalid_request");
 90→    const step = typeof item.step_id === "string" ? ` step_id=${item.step_id}` : "";
 91→    const path = Array.isArray(item.path)
 92→      ? ` path=${(item.path as unknown[]).join("→")}`
 93→      : "";
 94→    const missing = typeof item.missing === "string" ? ` missing=${item.missing}` : "";
 95→    return `HTTP ${status} ${code}${step}${path}${missing}`;
 96→  });
 97→  ui.errors.textContent = lines.length > 0 ? lines.join("\n") : `HTTP ${status}`;
 98→}
 99→
100→function clearErrors(): void {
101→  ui.errors.textContent = "";
102→}
103→
104→function buildBody(): Json {
105→  const body = JSON.parse(ui.plan.value) as Json;
106→  const tools: Record<string, Json> = {};
107→  for (const tool of TOOLS) {
108→    tools[tool] = {
109→      latency_ms: Number(byId<HTMLInputElement>(`latency-${tool}`).value),
110→      failure_rate: Number(byId<HTMLInputElement>(`rate-${tool}`).value),
111→    };
112→  }
113→  return {
114→    ...body,
115→    n: Number(ui.concurrency.value),
116→    tools,
117→    time_scale: typeof body.time_scale === "number" ? body.time_scale : 1,
118→  };
119→}
120→
121→async function loadExample(): Promise<void> {
122→  const { status, body } = await fetchJson<Json>("/api/example");
123→  if (status !== 200) {
124→    showErrors(status, body);
125→    return;
126→  }
127→  clearErrors();
128→  ui.plan.value = JSON.stringify(body, null, 2);
129→  if (typeof body.n === "number") {
130→    ui.concurrency.value = String(body.n);
131→  }
132→  const tools = body.tools as Record<string, Json> | undefined;
133→  if (tools) {
134→    for (const tool of TOOLS) {
135→      const config = tools[tool];
136→      if (!config) {
137→        continue;
138→      }
139→      const latency = byId<HTMLInputElement>(`latency-${tool}`);
140→      const rate = byId<HTMLInputElement>(`rate-${tool}`);
141→      if (typeof config.latency_ms === "number") {
142→        latency.value = String(config.latency_ms);
143→      }
144→      if (typeof config.failure_rate === "number") {
145→        rate.value = String(config.failure_rate);
146→      }
147→      latency.dispatchEvent(new Event("input"));
148→      rate.dispatchEvent(new Event("input"));
149→    }
150→  }
151→}
152→
153→function renderChart(n: number): void {
154→  const points: ConcurrencyPoint[] = concurrentSeries(events);
155→  if (points.length === 0) {
156→    ui.chart.innerHTML = '<svg viewBox="0 0 600 180"></svg>';
157→    return;
158→  }
159→  const first = points[0].seq;
160→  const last = points[points.length - 1].seq;
161→  const span = Math.max(1, last - first);
162→  const peak = points.reduce((max, point) => Math.max(max, point.count), 0);
163→  const scale = Math.max(n, peak, 1);
164→  const x = (seq: number): number => 40 + ((seq - first) / span) * 540;
165→  const y = (count: number): number => 150 - (count / scale) * 120;
166→  const line = points
167→    .map((point) => `${x(point.seq).toFixed(1)},${y(point.count).toFixed(1)}`)
168→    .join(" ");
169→  const baseline = y(n).toFixed(1);
170→  const dots = points
171→    .map(
172→      (point) =>
173→        `<circle cx="${x(point.seq).toFixed(1)}" cy="${y(point.count).toFixed(1)}" r="2" fill="#2563eb" />`,
174→    )
175→    .join("");
176→  ui.chart.innerHTML = `
177→    <svg viewBox="0 0 600 180" role="img" aria-label="concurrency">
178→      <line x1="40" y1="150" x2="580" y2="150" stroke="#94a3b8" />
179→      <line x1="40" y1="${baseline}" x2="580" y2="${baseline}" stroke="#dc2626" stroke-dasharray="6 4" />
180→      <text x="4" y="${baseline}" font-size="11" fill="#b91c1c">n=${n}</text>
181→      <polyline fill="none" stroke="#2563eb" stroke-width="2" points="${line}" />
182→      ${dots}
183→      <text x="40" y="170" font-size="11" fill="#64748b">seq ${first}</text>
184→      <text x="580" y="170" font-size="11" fill="#64748b" text-anchor="end">seq ${last}</text>
185→    </svg>`;
186→}
187→
188→function renderTimeline(): void {
189→  const rows: Row[] = parseRows(events);
190→  if (rows.length === 0) {
191→    ui.timeline.textContent = "no events";
192→    return;
193→  }
194→  const first = Math.min(...events.map((event) => event.seq));
195→  const last = Math.max(...events.map((event) => event.seq));
196→  const span = Math.max(1, last - first);
197→  ui.timeline.innerHTML = "";
198→  for (const row of rows) {
199→    const line = document.createElement("div");
200→    line.className = "timeline-row";
201→    const name = document.createElement("span");
202→    name.textContent = row.step_id;
203→    const track = document.createElement("div");
204→    track.className = "track";
205→    for (const segment of row.segments) {
206→      const node = document.createElement("div");
207→      node.className = `seg ${segment.kind}`;
208→      node.style.left = `${((segment.start - first) / span) * 100}%`;
209→      node.style.width = `${Math.max(0.8, ((segment.end - segment.start) / span) * 100)}%`;
210→      node.title = `${segment.kind} attempt=${segment.attempt ?? "-"} ts=${segment.startTs}..${segment.endTs}`;
211→      node.textContent = segment.kind === "running" && segment.attempt ? `a${segment.attempt}` : "";
212→      track.appendChild(node);
213→    }
214→    const terminal = document.createElement("span");
215→    terminal.textContent = row.terminal ?? "";
216→    line.append(name, track, terminal);
217→    ui.timeline.appendChild(line);
218→  }
219→}
220→
221→function renderEvents(): void {
222→  ui.eventTable.innerHTML = "";
223→  for (const event of events) {
224→    const tr = document.createElement("tr");
225→    const values = [
226→      String(event.seq),
227→      event.type,
228→      event.step_id ?? "",
229→      event.attempt === null ? "" : String(event.attempt),
230→    ];
231→    for (const value of values) {
232→      const td = document.createElement("td");
233→      td.textContent = value;
234→      tr.appendChild(td);
235→    }
236→    ui.eventTable.appendChild(tr);
237→  }
238→}
239→
240→function renderHistory(): void {
241→  ui.history.innerHTML = "";
242→  for (const record of runs) {
243→    const tr = document.createElement("tr");
244→    const values = [
245→      record.run_id,
246→      String(record.n),
247→      record.status,
248→      record.duration_ms === null ? "-" : String(record.duration_ms),
249→    ];
250→    for (const value of values) {
251→      const td = document.createElement("td");
252→      td.textContent = value;
253→      tr.appendChild(td);
254→    }
255→    ui.history.appendChild(tr);
256→  }
257→}
258→
259→function render(): void {
260→  renderChart(currentN);
261→  renderTimeline();
262→  renderEvents();
263→}
264→
265→function recordRun(snapshot: Snapshot): void {
266→  const started = events.find((event) => event.type === "run_started");
267→  const finished = events.find((event) => event.type === "run_finished");
268→  const duration = started && finished ? finished.ts - started.ts : null;
269→  const existing = runs.find((record) => record.run_id === snapshot.run_id);
270→  if (existing) {
271→    if (existing.duration_ms === null && duration !== null) {
272→      existing.duration_ms = duration;
273→      renderHistory();
274→    }
275→    return;
276→  }
277→  runs.unshift({
278→    run_id: snapshot.run_id,
279→    n: snapshot.n,
280→    status: snapshot.status,
281→    duration_ms: duration,
282→  });
283→  if (runs.length > 8) {
284→    runs.pop();
285→  }
286→  renderHistory();
287→}
288→
289→function showSnapshot(snapshot: Snapshot): void {
290→  currentN = snapshot.n;
291→  ui.status.textContent = `${snapshot.run_id} | ${snapshot.status} | seq=${snapshot.last_seq}`;
292→  if (snapshot.final_text) {
293→    ui.final.textContent = snapshot.final_text;
294→  }
295→  if (FINISHED.has(snapshot.status)) {
296→    ui.cancel.disabled = true;
297→  }
298→  recordRun(snapshot);
299→  render();
300→}
301→
302→async function loadSnapshot(run: string): Promise<Snapshot | null> {
303→  const { status, body } = await fetchJson<Snapshot>(`/api/runs/${run}`);
304→  if (status !== 200 || typeof body.run_id !== "string") {
305→    return null;
306→  }
307→  showSnapshot(body);
308→  return body;
309→}
310→
311→function acceptEvent(event: RunEvent): void {
312→  if (event.seq <= lastSeq) {
313→    return;
314→  }
315→  events.push(event);
316→  lastSeq = event.seq;
317→  render();
318→  if (event.type === "run_finished") {
319→    source?.close();
320→    source = null;
321→    void loadSnapshot(runId as string);
322→  }
323→}
324→
325→async function backfill(run: string): Promise<void> {
326→  const response = await fetch(`/api/runs/${run}/events`, {
327→    headers: { "Last-Event-ID": String(lastSeq) },
328→  });
329→  if (!response.ok) {
330→    return;
331→  }
332→  const text = await response.text();
333→  for (const block of text.split("\n\n")) {
334→    const dataLine = block.split("\n").find((line) => line.startsWith("data: "));
335→    if (!dataLine) {
336→      continue;
337→    }
338→    try {
339→      acceptEvent(JSON.parse(dataLine.slice(6)) as RunEvent);
340→    } catch {
341→      // Ignore malformed SSE frames from a partial response.
342→    }
343→  }
344→}
345→
346→function openStream(run: string): void {
347→  source?.close();
348→  source = new EventSource(`/api/runs/${run}/events`);
349→  source.onmessage = (message: MessageEvent<string>) => {
350→    acceptEvent(JSON.parse(message.data) as RunEvent);
351→  };
352→  source.onerror = () => {
353→    source?.close();
354→    source = null;
355→    void recover(run);
356→  };
357→}
358→
359→/** On disconnect, fetch the snapshot first, then replay the missing tail.
360→ * EventSource resends the last received id as Last-Event-ID on reconnect. */
361→async function recover(run: string): Promise<void> {
362→  try {
363→    const snapshot = await loadSnapshot(run);
364→    if (!snapshot) {
365→      return;
366→    }
367→    if (FINISHED.has(snapshot.status)) {
368→      if (snapshot.last_seq > lastSeq) {
369→        await backfill(run);
370→      }
371→    } else {
372→      openStream(run);
373→    }
374→  } catch (error) {
375→    ui.status.textContent = `reconnect failed: ${String(error)}`;
376→  }
377→}
378→
379→async function startRun(): Promise<void> {
380→  let body: Json;
381→  try {
382→    body = buildBody();
383→  } catch (error) {
384→    showErrors(0, { errors: [{ error: "invalid_json", detail: String(error) }] });
385→    return;
386→  }
387→  const response = await fetchJson<Json>("/api/runs", {
388→    method: "POST",
389→    headers: { "Content-Type": "application/json" },
390→    body: JSON.stringify(body),
391→  });
392→  if (response.status !== 202) {
393→    showErrors(response.status, response.body);
394→    return;
395→  }
396→  clearErrors();
397→  const id = String(response.body.run_id);
398→  runId = id;
399→  events = [];
400→  lastSeq = 0;
401→  currentN = Number(body.n ?? 2);
402→  ui.status.textContent = `${id} | RUNNING`;
403→  ui.final.textContent = "";
404→  ui.cancel.disabled = false;
405→  render();
406→  openStream(id);
407→}
408→
409→async function cancelRun(): Promise<void> {
410→  if (!runId) {
411→    return;
412→  }
413→  const response = await fetchJson<Json>(`/api/runs/${runId}/cancel`, {
414→    method: "POST",
415→  });
416→  if (response.status !== 200) {
417→    showErrors(response.status, response.body);
418→    return;
419→  }
420→  ui.status.textContent = `${runId} | CANCELLED`;
421→  await recover(runId);
422→}
