424→for (const tool of TOOLS) {
425→  const latency = byId<HTMLInputElement>(`latency-${tool}`);
426→  const rate = byId<HTMLInputElement>(`rate-${tool}`);
427→  const latencyOut = byId<HTMLOutputElement>(`latency-${tool}-out`);
428→  const rateOut = byId<HTMLOutputElement>(`rate-${tool}-out`);
429→  const sync = (): void => {
430→    latencyOut.value = latency.value;
431→    rateOut.value = Number(rate.value).toFixed(2);
432→  };
433→  latency.addEventListener("input", sync);
434→  rate.addEventListener("input", sync);
435→  sync();
436→}
