  1→/** Pure event-to-view transforms. No DOM access and no requests. */
  2→
  3→export interface RunEvent {
  4→  seq: number;
  5→  ts: number;
  6→  type: string;
  7→  run_id: string;
  8→  step_id: string | null;
  9→  attempt: number | null;
 10→  payload: Record<string, unknown>;
 11→}
 12→
 13→export type SegmentKind =
 14→  | "queued"
 15→  | "running"
 16→  | "retry_wait"
 17→  | "failed"
 18→  | "skipped"
 19→  | "cancelled";
 20→
 21→export interface Segment {
 22→  kind: SegmentKind;
 23→  start: number;
 24→  end: number;
 25→  attempt: number | null;
 26→  startTs: number;
 27→  endTs: number;
 28→}
 29→
 30→export interface Row {
 31→  step_id: string;
 32→  segments: Segment[];
 33→  terminal: string | null;
 34→}
 35→
 36→export interface ConcurrencyPoint {
 37→  seq: number;
 38→  count: number;
 39→}
 40→
 41→function ordered(events: RunEvent[]): RunEvent[] {
 42→  return [...events].sort((a, b) => a.seq - b.seq);
 43→}
 44→
 45→/**
 46→ * Build one row per step. Segment bounds use seq because it is strictly monotonic;
 47→ * ts values are retained for display. A succeeded step ends its running segment
 48→ * without adding a separate segment kind.
 49→ */
 50→export function parseRows(events: RunEvent[]): Row[] {
 51→  const grouped = new Map<string, RunEvent[]>();
 52→  for (const event of ordered(events)) {
 53→    if (!event.step_id) {
 54→      continue;
 55→    }
 56→    const list = grouped.get(event.step_id) ?? [];
 57→    list.push(event);
 58→    grouped.set(event.step_id, list);
 59→  }
 60→
 61→  const rows: Row[] = [];
 62→  for (const [step_id, list] of grouped) {
 63→    const segments: Segment[] = [];
 64→    let terminal: string | null = null;
 65→
 66→    for (let index = 0; index < list.length; index += 1) {
 67→      const event = list[index];
 68→      const next = list[index + 1];
 69→      const endSeq = next ? next.seq : event.seq + 1;
 70→      const endTs = next ? next.ts : event.ts;
 71→      const add = (kind: SegmentKind, attempt: number | null): void => {
 72→        segments.push({
 73→          kind,
 74→          start: event.seq,
 75→          end: Math.max(endSeq, event.seq + 1),
 76→          attempt,
 77→          startTs: event.ts,
 78→          endTs,
 79→        });
 80→      };
 81→
 82→      switch (event.type) {
 83→        case "step_queued":
 84→          add("queued", null);
 85→          break;
 86→        case "step_started":
 87→          add("running", event.attempt);
 88→          break;
 89→        case "step_retry_scheduled":
 90→          add("retry_wait", event.attempt);
 91→          break;
 92→        case "step_failed":
 93→          add("failed", event.attempt);
 94→          terminal = "FAILED";
 95→          break;
 96→        case "step_skipped":
 97→          add("skipped", null);
 98→          terminal = "SKIPPED";
 99→          break;
100→        case "step_cancelled":
101→          add("cancelled", null);
102→          terminal = "CANCELLED";
103→          break;
104→        case "step_succeeded":
105→          terminal = "SUCCEEDED";
106→          break;
107→        default:
108→          break;
109→      }
110→    }
111→    rows.push({ step_id, segments, terminal });
112→  }
113→  return rows;
114→}
115→
116→/** Count RUNNING steps after each step event. A step is active between
117→ * step_started and the first of succeeded / failed / retry_scheduled / cancelled. */
118→export function concurrentSeries(events: RunEvent[]): ConcurrencyPoint[] {
119→  const active = new Set<string>();
120→  let count = 0;
121→  const points: ConcurrencyPoint[] = [];
122→
123→  for (const event of ordered(events)) {
124→    if (!event.step_id) {
125→      continue;
126→    }
127→    if (event.type === "step_started") {
128→      if (!active.has(event.step_id)) {
129→        active.add(event.step_id);
130→        count += 1;
131→      }
132→    } else if (
133→      event.type === "step_succeeded" ||
134→      event.type === "step_failed" ||
135→      event.type === "step_retry_scheduled" ||
136→      event.type === "step_cancelled"
137→    ) {
138→      if (active.delete(event.step_id)) {
139→        count -= 1;
140→      }
141→    }
142→    points.push({ seq: event.seq, count });
143→  }
144→  return points;
145→}
